values
  ('65ed89d0-d8ef-499e-a23f-1e3612b60437', 'c3d4e5f6-7a8b-4d97-8a67-7e8f9a0b1c77', null, 'topic'::public.curated_course_node_type, 'Enlightenment, Neoclassicism, and Revolutionary Space', 'This section establishes the transition from pre-modern traditions to modern architectural history. Students learn how archaeology, political revolution, and Enlightenment thought changed the meanings of public buildings, monuments, and cities.', 0),
  ('fac2db49-d784-4436-b3a8-e70d2cab5561', 'c3d4e5f6-7a8b-4d97-8a67-7e8f9a0b1c77', '65ed89d0-d8ef-499e-a23f-1e3612b60437', 'subtopic'::public.curated_course_node_type, 'Classical Revival and Archaeological Knowledge', 'Neoclassicism used antiquity as evidence, language, and ideology rather than mere decoration.', 0),
  ('7e0c723b-70b7-47b6-aab9-58306d87a7db', 'c3d4e5f6-7a8b-4d97-8a67-7e8f9a0b1c77', 'fac2db49-d784-4436-b3a8-e70d2cab5561', 'concept'::public.curated_course_node_type, 'Pompeii, Herculaneum, Greece, and archaeological empiricism', null, 0),
