  ('ba919be3-f38a-4492-989a-9acffb237d44', 'c3d4e5f6-7a8b-4d97-8a67-7e8f9a0b1c77', '65ed89d0-d8ef-499e-a23f-1e3612b60437', 'subtopic'::public.curated_course_node_type, 'Neoclassicism''s Afterlives', 'Students trace how classical language persisted, mutated, and was challenged in modern architecture.', 2),
