  ('b85cf29b-0a2a-46c1-a65d-bc30ffe1d049', 'c3d4e5f6-7a8b-4d97-8a67-7e8f9a0b1c77', 'ba919be3-f38a-4492-989a-9acffb237d44', 'concept'::public.curated_course_node_type, 'Neoclassical echoes in modern and postmodern design', null, 3),
  ('5131c044-f4a9-4669-94c2-eccd07f318f3', 'c3d4e5f6-7a8b-4d97-8a67-7e8f9a0b1c77', null, 'topic'::public.curated_course_node_type, 'Industrialization, Iron, Glass, and Infrastructure', 'This unit shows that modern architecture emerged from new economies, technologies, and urban conditions. The point is to connect form to production, transportation, materials, labor, and the industrial city.', 1),
  ('63765bdc-9588-4351-9ad1-d1b559e3bfc7', 'c3d4e5f6-7a8b-4d97-8a67-7e8f9a0b1c77', '5131c044-f4a9-4669-94c2-eccd07f318f3', 'subtopic'::public.curated_course_node_type, 'New Materials and Building Systems', 'Iron, steel, glass, elevators, and reinforced concrete opened new spans, heights, programs, and forms of enclosure.', 0),
  ('66ef948e-9987-4b1e-8c90-910426a7995e', 'c3d4e5f6-7a8b-4d97-8a67-7e8f9a0b1c77', '63765bdc-9588-4351-9ad1-d1b559e3bfc7', 'concept'::public.curated_course_node_type, 'Crystal Palace and exhibition architecture', null, 0),
