  ('6ff45eb7-e95a-4f1e-8a8b-0159e56aa47b', 'c3d4e5f6-7a8b-4d97-8a67-7e8f9a0b1c77', '63765bdc-9588-4351-9ad1-d1b559e3bfc7', 'concept'::public.curated_course_node_type, 'Elevators, fireproofing, and the skyscraper frame', null, 2),
  ('292eadc3-e9a1-4aa7-8d37-7a4d740b09a5', 'c3d4e5f6-7a8b-4d97-8a67-7e8f9a0b1c77', '63765bdc-9588-4351-9ad1-d1b559e3bfc7', 'concept'::public.curated_course_node_type, 'Engineering versus architecture as a modern debate', null, 3),
  ('8dbf5837-21af-4f3a-9d27-20ef9ba52967', 'c3d4e5f6-7a8b-4d97-8a67-7e8f9a0b1c77', '5131c044-f4a9-4669-94c2-eccd07f318f3', 'subtopic'::public.curated_course_node_type, 'The Industrial City', 'Students examine how urban growth created problems of sanitation, mobility, housing, labor, and governance.', 1),
