  ('fed87636-1905-4304-9cc5-52c3275b9091', 'c3d4e5f6-7a8b-4d97-8a67-7e8f9a0b1c77', null, 'topic'::public.curated_course_node_type, 'Arts and Crafts, Reform, and Domestic Modernity', 'Arts and Crafts offers an early critique of industrial modernity. Students study craft not as nostalgia alone, but as a social, ethical, aesthetic, and political position.', 2),
  ('464ae7b3-2c2e-4500-8757-f6ccd9fe3165', 'c3d4e5f6-7a8b-4d97-8a67-7e8f9a0b1c77', 'fed87636-1905-4304-9cc5-52c3275b9091', 'subtopic'::public.curated_course_node_type, 'Craft, Labor, and Anti-Industrial Critique', 'Students learn why craft reformers tied beauty to labor, material honesty, and social life.', 0),
