  ('649cc34f-4dd5-4c1f-8f81-015d12feb11a', 'c3d4e5f6-7a8b-4d97-8a67-7e8f9a0b1c77', 'fed87636-1905-4304-9cc5-52c3275b9091', 'subtopic'::public.curated_course_node_type, 'Domestic Architecture and Everyday Life', 'The house became a site where modern ideals of comfort, gender, health, and identity were debated.', 1),
