  ('7b8330b2-2e15-421b-b97e-eb767435050c', 'c3d4e5f6-7a8b-4d97-8a67-7e8f9a0b1c77', null, 'topic'::public.curated_course_node_type, 'Le Corbusier, Mies, Wright, and the Canon of High Modernism', 'The canonical modernists remain central because their projects shaped architectural education, criticism, and practice. This section teaches the canon while also asking how it became canonical.', 5),
