  ('1229fcc3-19ac-426f-8f92-9c6f8736e8e1', 'c3d4e5f6-7a8b-4d97-8a67-7e8f9a0b1c77', '1c1216c9-1f1c-4b02-b2c9-8e70ecd69518', 'concept'::public.curated_course_node_type, 'Material discipline and spatial ideology', null, 3),
