  ('3e38a3c8-6e31-4b55-906f-e86d1c2c4eb3', 'c3d4e5f6-7a8b-4d97-8a67-7e8f9a0b1c77', null, 'topic'::public.curated_course_node_type, 'Bauhaus, Design Pedagogy, and Standardization', 'This section studies the Bauhaus as school, myth, network, pedagogy, and cultural export. Students learn how design education connected art, craft, industry, politics, and everyday objects.', 6),
  ('efee9520-99c3-4b35-aae0-cbd1723cdf41', 'c3d4e5f6-7a8b-4d97-8a67-7e8f9a0b1c77', '3e38a3c8-6e31-4b55-906f-e86d1c2c4eb3', 'subtopic'::public.curated_course_node_type, 'Bauhaus Curriculum and Workshops', 'Students examine how pedagogy shaped modern design thinking from preliminary courses to workshops.', 0),
  ('a0301624-bb82-4d91-812a-c4218e3f3e63', 'c3d4e5f6-7a8b-4d97-8a67-7e8f9a0b1c77', 'efee9520-99c3-4b35-aae0-cbd1723cdf41', 'concept'::public.curated_course_node_type, 'Gropius, Meyer, Mies, Itten, Moholy-Nagy, Albers, and Brandt', null, 0),
