  ('16d07442-b003-4110-9e14-ceec8d4b5fd5', 'c3d4e5f6-7a8b-4d97-8a67-7e8f9a0b1c77', 'efee9520-99c3-4b35-aae0-cbd1723cdf41', 'concept'::public.curated_course_node_type, 'Typography, furniture, textiles, theater, and photography', null, 2),
  ('ac97d435-be40-491f-b639-341b875e5837', 'c3d4e5f6-7a8b-4d97-8a67-7e8f9a0b1c77', 'efee9520-99c3-4b35-aae0-cbd1723cdf41', 'concept'::public.curated_course_node_type, 'Collective work and disciplinary integration', null, 3),
  ('2c2982a2-4ec9-4b9e-93eb-2458cc293dc4', 'c3d4e5f6-7a8b-4d97-8a67-7e8f9a0b1c77', '3e38a3c8-6e31-4b55-906f-e86d1c2c4eb3', 'subtopic'::public.curated_course_node_type, 'Standardization, Industry, and Housing', 'The Bauhaus linked design reform to mass production, affordability, and social need.', 1),
