  ('9b142148-313a-4ad5-8c3e-7b31455db469', 'c3d4e5f6-7a8b-4d97-8a67-7e8f9a0b1c77', null, 'topic'::public.curated_course_node_type, 'International Style, CIAM, and Modernism as Global Language', 'This unit studies modernism''s institutionalization and global circulation. Students learn how a style promoted as universal was shaped by exhibitions, professional networks, colonial conditions, and local adaptation.', 7),
