  ('afc172c7-a3cb-4136-bbe0-13405f9a83ba', 'c3d4e5f6-7a8b-4d97-8a67-7e8f9a0b1c77', '9b142148-313a-4ad5-8c3e-7b31455db469', 'subtopic'::public.curated_course_node_type, 'CIAM, Functional City, and Planning', 'This subtopic covers modernist planning as an attempt to rationalize housing, work, recreation, and circulation.', 1),
