  ('57645330-9adf-4ec9-8196-5a9cdee2040a', 'c3d4e5f6-7a8b-4d97-8a67-7e8f9a0b1c77', null, 'topic'::public.curated_course_node_type, 'Corporate Modernism, Glass Towers, and Late Capitalist Urbanism', 'This section studies the postwar office tower and corporate campus as architectural expressions of management, finance, bureaucracy, globalization, and image.', 10),
