  ('e57f1a08-2e02-4178-9c6c-e92800181cd1', 'c3d4e5f6-7a8b-4d97-8a67-7e8f9a0b1c77', 'a05ebcc3-0a80-4c5a-8782-99c5473d0c27', 'concept'::public.curated_course_node_type, 'Ducks, decorated sheds, signs, and symbolism', null, 2),
