  ('a122e254-9dac-4e9a-a7f8-009289804d24', 'c3d4e5f6-7a8b-4d97-8a67-7e8f9a0b1c77', '4d786eca-06e2-4fbb-bab1-f60d502765e3', 'concept'::public.curated_course_node_type, 'Market imagery and themed environments', null, 1),
  ('172e07be-32d3-4309-8899-03ff205990e5', 'c3d4e5f6-7a8b-4d97-8a67-7e8f9a0b1c77', '4d786eca-06e2-4fbb-bab1-f60d502765e3', 'concept'::public.curated_course_node_type, 'Identity, pluralism, and representation', null, 2),
  ('649cda3d-c3f9-4116-b2b4-2ffa77c9bbc7', 'c3d4e5f6-7a8b-4d97-8a67-7e8f9a0b1c77', '4d786eca-06e2-4fbb-bab1-f60d502765e3', 'concept'::public.curated_course_node_type, 'Postmodern preservation and heritage culture', null, 3),
  ('20f4d84c-ab08-4204-863a-cebf34e45d5f', 'c3d4e5f6-7a8b-4d97-8a67-7e8f9a0b1c77', null, 'topic'::public.curated_course_node_type, 'Deconstructivism, Critical Theory, and Late 20th-Century Discourse', 'This unit connects architecture to language, philosophy, media, institutional critique, and the late twentieth-century theory boom. Students learn to read buildings and texts together.', 12),
  ('a23b4366-fd04-4f45-b6d2-9a364e695110', 'c3d4e5f6-7a8b-4d97-8a67-7e8f9a0b1c77', '20f4d84c-ab08-4204-863a-cebf34e45d5f', 'subtopic'::public.curated_course_node_type, 'Deconstructivist Form and Theory', 'Students study fragmentation, instability, and dislocation as formal and theoretical strategies.', 0),
  ('15c7f99b-f170-45e6-bd65-777e548beadd', 'c3d4e5f6-7a8b-4d97-8a67-7e8f9a0b1c77', 'a23b4366-fd04-4f45-b6d2-9a364e695110', 'concept'::public.curated_course_node_type, 'Derrida, Eisenman, Tschumi, Libeskind, Hadid, Coop Himmelb(l)au', null, 0),
  ('4ca568f3-fb38-4516-9d15-d1da15b9fb81', 'c3d4e5f6-7a8b-4d97-8a67-7e8f9a0b1c77', 'a23b4366-fd04-4f45-b6d2-9a364e695110', 'concept'::public.curated_course_node_type, 'MoMA 1988 Deconstructivist Architecture exhibition', null, 1),
  ('31109198-4b6c-4ddb-8944-3dc5286db4fb', 'c3d4e5f6-7a8b-4d97-8a67-7e8f9a0b1c77', 'a23b4366-fd04-4f45-b6d2-9a364e695110', 'concept'::public.curated_course_node_type, 'Grid, trace, event, and disjunction', null, 2),
  ('109a1c3a-fc24-4db4-8e56-7b611c0b2a22', 'c3d4e5f6-7a8b-4d97-8a67-7e8f9a0b1c77', 'a23b4366-fd04-4f45-b6d2-9a364e695110', 'concept'::public.curated_course_node_type, 'Form, philosophy, and spectacle', null, 3),
  ('5ec7e644-c6d6-4588-a243-577b7ff5a919', 'c3d4e5f6-7a8b-4d97-8a67-7e8f9a0b1c77', '20f4d84c-ab08-4204-863a-cebf34e45d5f', 'subtopic'::public.curated_course_node_type, 'Critical Theory and Architectural Texts', 'This subtopic trains students to read theory as evidence and argument rather than as jargon.', 1),
  ('b7fe1bf0-68d0-4e23-8912-e87fb4e4ce7a', 'c3d4e5f6-7a8b-4d97-8a67-7e8f9a0b1c77', '5ec7e644-c6d6-4588-a243-577b7ff5a919', 'concept'::public.curated_course_node_type, 'Semiotics, phenomenology, Marxism, feminism, and poststructuralism', null, 0);
