  ('1d76f4a2-86e7-43ee-b14a-add8a505901c', 'c3d4e5f6-7a8b-4d97-8a67-7e8f9a0b1c77', '3e41c623-6b81-4930-b7f8-60c3bfceab80', 'concept'::public.curated_course_node_type, 'Drawings, models, and publication culture', null, 2),
  ('7455993e-8b95-4cad-b4a8-ed39fd30ee5c', 'c3d4e5f6-7a8b-4d97-8a67-7e8f9a0b1c77', '3e41c623-6b81-4930-b7f8-60c3bfceab80', 'concept'::public.curated_course_node_type, 'Star systems and institutional power', null, 3),
  ('9766fef4-c3a2-4a12-a1b1-3e21ce8ba724', 'c3d4e5f6-7a8b-4d97-8a67-7e8f9a0b1c77', null, 'topic'::public.curated_course_node_type, 'Global Modernisms, Colonialism, Decolonial Critique, and Critical Regionalism', 'This section expands the course beyond a Euro-American sequence. Students learn to study modern architecture as global exchange shaped by empire, migration, climate, materials, nationalism, and resistance.', 13),
  ('aeb3807b-240b-49ae-8d4b-eb2448fbd027', 'c3d4e5f6-7a8b-4d97-8a67-7e8f9a0b1c77', '9766fef4-c3a2-4a12-a1b1-3e21ce8ba724', 'subtopic'::public.curated_course_node_type, 'Colonial Modernity and Architectural Exchange', 'Students examine how colonial power shaped buildings, planning, labor, and knowledge circulation.', 0),
  ('1855d474-5277-4e44-9619-24bea8b22925', 'c3d4e5f6-7a8b-4d97-8a67-7e8f9a0b1c77', 'aeb3807b-240b-49ae-8d4b-eb2448fbd027', 'concept'::public.curated_course_node_type, 'Colonial capitals, schools, hospitals, housing, and infrastructure', null, 0),
  ('be30508c-a8af-45a5-bf9a-09cb0a950cff', 'c3d4e5f6-7a8b-4d97-8a67-7e8f9a0b1c77', 'aeb3807b-240b-49ae-8d4b-eb2448fbd027', 'concept'::public.curated_course_node_type, 'Missionary, administrative, and commercial architecture', null, 1),
  ('c36d3a21-e61f-4ba0-a211-6da11f008e72', 'c3d4e5f6-7a8b-4d97-8a67-7e8f9a0b1c77', 'aeb3807b-240b-49ae-8d4b-eb2448fbd027', 'concept'::public.curated_course_node_type, 'Tropical expertise and climatic design', null, 2),
  ('0c60c565-d26b-45ec-95b5-28204cd75000', 'c3d4e5f6-7a8b-4d97-8a67-7e8f9a0b1c77', 'aeb3807b-240b-49ae-8d4b-eb2448fbd027', 'concept'::public.curated_course_node_type, 'Archives, extraction, and asymmetrical exchange', null, 3),
  ('d93ddd8a-10fa-4467-a10e-8d6f6dcf3a53', 'c3d4e5f6-7a8b-4d97-8a67-7e8f9a0b1c77', '9766fef4-c3a2-4a12-a1b1-3e21ce8ba724', 'subtopic'::public.curated_course_node_type, 'Postcolonial Nation-Building and Global Modernisms', 'This subtopic studies modern architecture as a tool of independence, development, and cultural identity.', 1),
  ('45d14344-30e7-4b2b-93f7-95bbc2754ee0', 'c3d4e5f6-7a8b-4d97-8a67-7e8f9a0b1c77', 'd93ddd8a-10fa-4467-a10e-8d6f6dcf3a53', 'concept'::public.curated_course_node_type, 'Chandigarh, Brasilia, Accra, Dakar, Mexico City, Tokyo, and beyond', null, 0),
  ('bc3bd174-2515-4ddf-a43e-ca121cef740b', 'c3d4e5f6-7a8b-4d97-8a67-7e8f9a0b1c77', 'd93ddd8a-10fa-4467-a10e-8d6f6dcf3a53', 'concept'::public.curated_course_node_type, 'State modernity and development planning', null, 1),
  ('3952c6e2-8cb9-41c2-be8b-1d33bd335c8f', 'c3d4e5f6-7a8b-4d97-8a67-7e8f9a0b1c77', 'd93ddd8a-10fa-4467-a10e-8d6f6dcf3a53', 'concept'::public.curated_course_node_type, 'Local architects and transnational networks', null, 2),
  ('84080e3d-c924-4ccc-b9eb-2ea53e1029e6', 'c3d4e5f6-7a8b-4d97-8a67-7e8f9a0b1c77', 'd93ddd8a-10fa-4467-a10e-8d6f6dcf3a53', 'concept'::public.curated_course_node_type, 'Modernism outside the center-periphery model', null, 3),
  ('03855668-b4f6-4c56-bc9c-98c325536205', 'c3d4e5f6-7a8b-4d97-8a67-7e8f9a0b1c77', '9766fef4-c3a2-4a12-a1b1-3e21ce8ba724', 'subtopic'::public.curated_course_node_type, 'Critical Regionalism and Decolonial Critique', 'Students assess critical regionalism and decolonial frameworks as methods for reading place, climate, culture, and power.', 2),
  ('fb8ccd8e-c43d-4101-810e-48b252d9a461', 'c3d4e5f6-7a8b-4d97-8a67-7e8f9a0b1c77', '03855668-b4f6-4c56-bc9c-98c325536205', 'concept'::public.curated_course_node_type, 'Frampton''s critical regionalism', null, 0),
  ('56b8616c-1272-45e7-b5d4-35eaf07fae97', 'c3d4e5f6-7a8b-4d97-8a67-7e8f9a0b1c77', '03855668-b4f6-4c56-bc9c-98c325536205', 'concept'::public.curated_course_node_type, 'Place, tectonics, topography, and climate', null, 1),
  ('8d20d9c6-8a93-4bb0-adaa-42fce89bc6d3', 'c3d4e5f6-7a8b-4d97-8a67-7e8f9a0b1c77', '03855668-b4f6-4c56-bc9c-98c325536205', 'concept'::public.curated_course_node_type, 'Indigenous, vernacular, and local knowledge', null, 2),
  ('624b2f61-4601-477c-81c6-4812e3345821', 'c3d4e5f6-7a8b-4d97-8a67-7e8f9a0b1c77', '03855668-b4f6-4c56-bc9c-98c325536205', 'concept'::public.curated_course_node_type, 'Risks of essentialism and exoticism', null, 3),
  ('87d43194-bc57-4167-ad77-be858d274f4d', 'c3d4e5f6-7a8b-4d97-8a67-7e8f9a0b1c77', null, 'topic'::public.curated_course_node_type, 'Race, Gender, Labor, and Architectural Production', 'This unit asks who appears in architectural history and who has been made invisible. Students study architecture as collective production involving designers, clients, builders, occupants, critics, and institutions.', 14),
  ('65c09ea3-021f-46fb-bd6f-4d66d1765051', 'c3d4e5f6-7a8b-4d97-8a67-7e8f9a0b1c77', '87d43194-bc57-4167-ad77-be858d274f4d', 'subtopic'::public.curated_course_node_type, 'Race, Segregation, and Spatial Inequality', 'Students connect architecture and planning to racial capitalism, segregation, displacement, and public policy.', 0),
  ('14a07e22-4101-4146-85a2-839129897577', 'c3d4e5f6-7a8b-4d97-8a67-7e8f9a0b1c77', '65c09ea3-021f-46fb-bd6f-4d66d1765051', 'concept'::public.curated_course_node_type, 'Redlining, urban renewal, and highway construction', null, 0),
  ('1ddd450f-1912-4c27-8765-709938cc562b', 'c3d4e5f6-7a8b-4d97-8a67-7e8f9a0b1c77', '65c09ea3-021f-46fb-bd6f-4d66d1765051', 'concept'::public.curated_course_node_type, 'Public housing and discriminatory policy', null, 1),
  ('5bf6b2a3-2da0-4633-ad5f-a5abc8f4c4ce', 'c3d4e5f6-7a8b-4d97-8a67-7e8f9a0b1c77', '65c09ea3-021f-46fb-bd6f-4d66d1765051', 'concept'::public.curated_course_node_type, 'Black, Indigenous, and minority architects', null, 2),
  ('1adae8a8-30c4-4264-9d80-7d34537bab7c', 'c3d4e5f6-7a8b-4d97-8a67-7e8f9a0b1c77', '65c09ea3-021f-46fb-bd6f-4d66d1765051', 'concept'::public.curated_course_node_type, 'Memory, monuments, and spatial justice', null, 3),
  ('01fc3e88-e8ce-4978-b326-208b7e003ee6', 'c3d4e5f6-7a8b-4d97-8a67-7e8f9a0b1c77', '87d43194-bc57-4167-ad77-be858d274f4d', 'subtopic'::public.curated_course_node_type, 'Gender, Authorship, and Professional Gatekeeping', 'This subtopic examines how gender shaped access to education, credit, practice, domestic design, and historiography.', 1),
  ('f47c4ecc-2aef-4d63-a226-e16ea461c407', 'c3d4e5f6-7a8b-4d97-8a67-7e8f9a0b1c77', '01fc3e88-e8ce-4978-b326-208b7e003ee6', 'concept'::public.curated_course_node_type, 'Women in modern architecture and design', null, 0),
  ('755f6017-45c7-4d06-a098-d51a43724307', 'c3d4e5f6-7a8b-4d97-8a67-7e8f9a0b1c77', '01fc3e88-e8ce-4978-b326-208b7e003ee6', 'concept'::public.curated_course_node_type, 'Invisible collaborators and office labor', null, 1),
  ('9a7973bf-e135-4794-aec1-a8e3276b9275', 'c3d4e5f6-7a8b-4d97-8a67-7e8f9a0b1c77', '01fc3e88-e8ce-4978-b326-208b7e003ee6', 'concept'::public.curated_course_node_type, 'Domesticity, care, and feminist space', null, 2),
  ('c4f175ae-2450-4c08-a52e-52570d2406ae', 'c3d4e5f6-7a8b-4d97-8a67-7e8f9a0b1c77', '01fc3e88-e8ce-4978-b326-208b7e003ee6', 'concept'::public.curated_course_node_type, 'Queer space and critique of normative environments', null, 3),
  ('be3e5fc6-f464-406a-bda5-a31ca427b655', 'c3d4e5f6-7a8b-4d97-8a67-7e8f9a0b1c77', '87d43194-bc57-4167-ad77-be858d274f4d', 'subtopic'::public.curated_course_node_type, 'Labor, Construction, and Material Supply Chains', 'Students learn to see buildings as products of labor, extraction, craft, maintenance, and risk.', 2),
  ('8e76f6bf-085e-4c7b-a3e1-d98be4e7aca5', 'c3d4e5f6-7a8b-4d97-8a67-7e8f9a0b1c77', 'be3e5fc6-f464-406a-bda5-a31ca427b655', 'concept'::public.curated_course_node_type, 'Construction workers, contractors, and fabricators', null, 0),
  ('2be14d45-b66f-4f40-b53d-b4821789d540', 'c3d4e5f6-7a8b-4d97-8a67-7e8f9a0b1c77', 'be3e5fc6-f464-406a-bda5-a31ca427b655', 'concept'::public.curated_course_node_type, 'Material extraction and embodied labor', null, 1),
  ('141a7050-bacc-45a9-b75c-d1902a7189be', 'c3d4e5f6-7a8b-4d97-8a67-7e8f9a0b1c77', 'be3e5fc6-f464-406a-bda5-a31ca427b655', 'concept'::public.curated_course_node_type, 'Maintenance, cleaning, and operations', null, 2),
  ('f592b46c-2c3f-409d-8077-060ccbd6f56c', 'c3d4e5f6-7a8b-4d97-8a67-7e8f9a0b1c77', 'be3e5fc6-f464-406a-bda5-a31ca427b655', 'concept'::public.curated_course_node_type, 'Ethics of authorship and credit', null, 3);
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('f3a109b7-193a-474b-b30d-c453a81e6b4e', 'c3d4e5f6-7a8b-4d97-8a67-7e8f9a0b1c77', null, 'topic'::public.curated_course_node_type, 'Sustainability, Technology, Media, and Ecological Thought', 'This section links modern architectural history to energy, media, systems, environmentalism, and technological imagination. Students learn how environmental questions were present before contemporary sustainability branding.', 15),
  ('af038b68-2e28-4033-9030-d2b321f7000f', 'c3d4e5f6-7a8b-4d97-8a67-7e8f9a0b1c77', 'f3a109b7-193a-474b-b30d-c453a81e6b4e', 'subtopic'::public.curated_course_node_type, 'Environmental Systems and Energy Histories', 'Students trace passive design, climate control, energy abundance, and oil-era building culture.', 0),
  ('0f24542c-acfb-461e-9bf8-caa327a951c7', 'c3d4e5f6-7a8b-4d97-8a67-7e8f9a0b1c77', 'af038b68-2e28-4033-9030-d2b321f7000f', 'concept'::public.curated_course_node_type, 'Sun, shade, ventilation, and climate-responsive design', null, 0),
