  ('3304b5a6-87d5-45fe-b161-71219367c7ec', 'c3d4e5f6-7a8b-4d97-8a67-7e8f9a0b1c77', 'af038b68-2e28-4033-9030-d2b321f7000f', 'concept'::public.curated_course_node_type, 'Energy crisis and ecological design', null, 2),
  ('2ae4dd49-7c23-4584-97a0-28f28acafa5c', 'c3d4e5f6-7a8b-4d97-8a67-7e8f9a0b1c77', 'af038b68-2e28-4033-9030-d2b321f7000f', 'concept'::public.curated_course_node_type, 'Carbon, retrofit, and preservation ethics', null, 3),
