  ('b391350a-e551-40cb-b31a-882e46c10bd5', 'c3d4e5f6-7a8b-4d97-8a67-7e8f9a0b1c77', 'b4f2fc07-0568-4655-a6fd-dc675a1312d8', 'concept'::public.curated_course_node_type, 'Photography and the modern canon', null, 0),
