  ('9aaae71c-00f2-44ab-b9ab-75e1be1e9185', 'c3d4e5f6-7a8b-4d97-8a67-7e8f9a0b1c77', 'b4f2fc07-0568-4655-a6fd-dc675a1312d8', 'concept'::public.curated_course_node_type, 'CAD, parametric design, and digital fabrication', null, 2),
